class Solution {
  public long splitArray(int[] nums) {
    int n = nums.length;
    int incLen = 1;
    while (incLen < n && nums[incLen] > nums[incLen - 1]) incLen++;
    int decStart = n - 1;
    while (decStart > 0 && nums[decStart - 1] > nums[decStart]) decStart--;
    long[] pre = new long[n + 1];
    for (int i = 0; i < n; i++) pre[i + 1] = pre[i] + nums[i];
    long best = -1;
    for (int i = Math.max(1, decStart); i <= Math.min(incLen, n - 1); i++) {
      long diff = Math.abs(pre[i] - (pre[n] - pre[i]));
      if (best < 0 || diff < best) best = diff;
    }
    return best;
  }
}
